/* atualiza a prévia do topo sem redesenhar o formulário (no celular, redesenhar fazia o toque no botão se perder) */
function updateClientPreview(){
  const d=S.editor.data, box=$("#c-prev"); if(!box)return;
  const col=/^#[0-9a-f]{6}$/i.test(d.color||"")?d.color:"#e55496";
  box.style.background=col; box.style.color=inkFor(col);
  const h=box.querySelector("h1"); if(h)h.textContent=d.name||"Nome do cliente";
  box.querySelectorAll(".ini").forEach(e=>e.textContent=initials(d.name));
  document.querySelectorAll(".logo-edit .ini").forEach(e=>e.textContent=initials(d.name));
}
function stickerOpts(st){return `<div class="opts">${DECISIONS.map(s=>`<button class="opt" draggable="true" data-drag="${s}" aria-label="${ST[s].long}" title="${ST[s].long}" aria-pressed="${st===s}" data-act="pick" data-s="${s}" ${S.busy?"disabled":""}><span class="mini">${sticker(s)}</span></button>`).join("")}</div>`}
function commentBox(){return S.commentOpen?`<div class="commentbox">
    <label class="field"><span>O que precisa ajustar?</span><textarea id="note" rows="3" placeholder="Ex.: trocar a foto da segunda arte e deixar o preço maior"></textarea></label>
    <label class="field"><span>Seu nome</span><input type="text" id="who" value="${esc(S.who)}" placeholder="Quem está pedindo o ajuste" autocomplete="name"></label>
    <div class="actions"><button class="btn brand" data-act="submit-comment" ${S.busy?"disabled":""}>Enviar comentário</button>${MOB()?`<button class="btn ghost" data-act="close-comment">Depois</button>`:""}</div></div>`:""}
function nameOf(h){return h.byLabel||"Cliente"}
function applyPost(post){const i=S.posts.findIndex(x=>x.id===post.id);if(i>=0)S.posts[i]=post;else S.posts.push(post)}
async function submitReview(status){
  const p=S.posts.find(x=>x.id===S.open); if(!p||S.busy)return;
  const prev=JSON.parse(JSON.stringify(p.review||{status:"pendente",history:[]}));
  p.review={...prev,status,at:new Date().toISOString(),byLabel:S.who||""};
  S.commentOpen=status==="alteracao"; S.pick=null; S.reviewErr=""; S.busy=true; render(); renderSheet();
  try{
    const r=await api(`/api/c/${S.token}/review`,{method:"POST",body:{postId:p.id,status,name:S.who}});
    applyPost(r.post); toast(ST[status].long);
  }catch(e){p.review=prev;S.commentOpen=false;S.reviewErr=e.message}
  S.busy=false; render(); if(!S.flying)renderSheet();
  if(S.commentOpen)setTimeout(()=>$("#note")?.focus(),50);
}
function nComments(id){return (reviewOf(id)?.history||[]).filter(h=>h.note&&(h.kind==="comment"||h.status!=="pendente")).length}
async function submitComment(){
  const p=S.posts.find(x=>x.id===S.open); if(!p||S.busy)return;
  const note=($("#note")?.value||"").trim();
  if(!note){S.reviewErr="Escreva o comentário antes de enviar.";renderSheet();$("#note")?.focus();return}
  S.busy=true;renderSheet();
  try{
    const r=S.isOwner?await api(`/api/admin/clients/${S.clientId}/posts/${p.id}/comment`,{method:"POST",body:{note}})
      :await api(`/api/c/${S.token}/comment`,{method:"POST",body:{postId:p.id,note,name:S.who}});
    applyPost(r.post);S.noteDraft="";S.reviewErr="";S.commentOpen=false;render();toast("Comentário enviado");
  }catch(e){S.reviewErr=e.message}
  S.busy=false;renderSheet();
}
function placeSticker(status,fromEl){
  if(S.busy)return;
  const from=fromEl?.getBoundingClientRect();
  S.pick=status;S.reviewErr="";
  const reduce=matchMedia("(prefers-reduced-motion: reduce)").matches;
  if(!from||reduce||!document.querySelector("[data-drop]")){S.flying=false;S.popped=S.open;submitReview(status);setTimeout(()=>{S.popped=null},600);return}
  S.flying=true;renderSheet();
  const target=document.querySelector(".ig-stk");
  if(!target){S.flying=false;submitReview(status);return}
  const media=document.querySelector("[data-drop]");
  media.scrollIntoView({block:"nearest",behavior:"smooth"});
  setTimeout(()=>{
    const to=document.querySelector(".ig-stk").getBoundingClientRect();
    const fl=document.createElement("div");fl.className="flyer";fl.innerHTML=sticker(status);
    Object.assign(fl.style,{left:from.left+"px",top:from.top+"px",width:from.width+"px"});
    document.body.appendChild(fl);
    const dx=to.left-from.left,dy=to.top-from.top,sc=to.width/from.width;
    const anim=fl.animate([{transform:"translate(0,0) scale(1) rotate(0deg)",transformOrigin:"0 0"},{transform:`translate(${dx}px,${dy-40}px) scale(${sc*1.15}) rotate(-14deg)`,transformOrigin:"0 0",offset:.8},{transform:`translate(${dx}px,${dy}px) scale(${sc}) rotate(-8deg)`,transformOrigin:"0 0"}],{duration:560,easing:"cubic-bezier(.3,.7,.3,1)"});
    anim.onfinish=()=>{fl.remove();S.flying=false;submitReview(status)};
  },media.getBoundingClientRect().top<0||media.getBoundingClientRect().bottom>innerHeight?320:0);
}
document.addEventListener("dragstart",ev=>{const t=ev.target.closest?.("[data-drag]");if(t){ev.dataTransfer.setData("text/plain",t.dataset.drag);ev.dataTransfer.effectAllowed="copy"}});
document.addEventListener("dragover",ev=>{const z=ev.target.closest?.("[data-drop]");if(z){ev.preventDefault();z.classList.add("over")}});
document.addEventListener("dragleave",ev=>{const z=ev.target.closest?.("[data-drop]");if(z&&!z.contains(ev.relatedTarget))z.classList.remove("over")});
document.addEventListener("drop",ev=>{const z=ev.target.closest?.("[data-drop]");if(!z)return;ev.preventDefault();const st=ev.dataTransfer.getData("text/plain");if(ST[st]&&st!=="pendente"&&!S.isOwner){S.popped=S.open;submitReview(st);setTimeout(()=>{S.popped=null},600)}});
async function resend(id){
  try{const r=await api(`/api/admin/clients/${S.clientId}/posts/${id}/resend`,{method:"POST"});applyPost(r.post);render();renderSheet();toast("Peça reenviada para aprovação")}catch(e){toast(e.message)}
}

