function get(o,k){return k.split(".").reduce((a,x)=>a?.[x],o)??""}
function setk(o,k,v){const ks=k.split(".");let t=o;ks.slice(0,-1).forEach(x=>{t[x]=t[x]||{};t=t[x]});t[ks.at(-1)]=v}

const IMG_LIMIT=8*1024*1024;
async function shrink(file){
  if(file.size<=IMG_LIMIT||!/^image\/(jpeg|png|webp)$/.test(file.type))return file;
  const bmp=await createImageBitmap(file);
  const sc=Math.min(1,2160/Math.max(bmp.width,bmp.height));
  const cv=document.createElement("canvas");cv.width=Math.round(bmp.width*sc);cv.height=Math.round(bmp.height*sc);
  cv.getContext("2d").drawImage(bmp,0,0,cv.width,cv.height);
  for(const q of [.92,.85,.75]){const b=await new Promise(r=>cv.toBlob(r,"image/jpeg",q));if(b&&b.size<=IMG_LIMIT)return b}
  return file;
}
function mediaType(file){if(file.type)return file.type;const n=file.name.toLowerCase();if(n.endsWith(".mov"))return "video/quicktime";if(n.endsWith(".mp4"))return "video/mp4";return ""}
/* envia em partes de 4 MB, assim vídeos grandes passam pelo limite do servidor */
async function uploadOne(file,onProgress){
  const type=mediaType(file);
  const f=await shrink(file);
  const start=await api(`/api/admin/clients/${S.clientId}/upload`,{method:"POST",body:{type:f.type||type,size:f.size}});
  const file_=start.id.split("/")[1];
  for(let i=0;i<start.chunks;i++){
    const part=f.slice(i*start.chunkSize,Math.min(f.size,(i+1)*start.chunkSize));
    let tries=0;
    for(;;){
      try{await api(`/api/admin/clients/${S.clientId}/upload/${file_}/${i}`,{method:"PUT",body:part,headers:{"content-type":"application/octet-stream"}});break}
      catch(e){if(++tries>=3)throw new Error(`Não deu para enviar "${file.name}". ${e.message}`)}
    }
    onProgress&&onProgress(Math.round((i+1)/start.chunks*100));
  }
  return {id:start.id,type:start.type};
}
async function uploadFiles(files){
  const list=[...files].slice(0,10-(S.editor.data.media||[]).length);
  if(!list.length){S.editor.err="O limite é de 10 artes por peça.";renderSheet();return}
  S.editor.uploading=true;S.editor.err="";renderSheet();
  for(const file of list){
    try{const r=await uploadOne(file,pc=>{if(S.editor){S.editor.progress=pc;renderSheet()}});S.editor.progress=0;S.editor.data.media=[...(S.editor.data.media||[]),{id:r.id,type:r.type}]}
    catch(e){S.editor.err=e.message}
    if(S.editor)renderSheet();
  }
  if(S.editor){S.editor.uploading=false;renderSheet()}
}
async function savePost(visible){
  const e=S.editor; if(!e||S.busy)return;
  const d=JSON.parse(JSON.stringify(e.data)); d.visible=visible;
  S.busy=true;renderSheet();
  try{
    const r=e.id?await api(`/api/admin/clients/${S.clientId}/posts/${e.id}`,{method:"PUT",body:d}):await api(`/api/admin/clients/${S.clientId}/posts`,{method:"POST",body:d});
    applyPost(r.post);S.busy=false;closeSheet();render();toast(visible?"Peça enviada para o cliente":"Rascunho salvo");
  }catch(err){S.busy=false;S.editor.err=err.message;renderSheet()}
}
async function deletePost(id){
  try{await api(`/api/admin/clients/${S.clientId}/posts/${id}`,{method:"DELETE"});S.posts=S.posts.filter(p=>p.id!==id);closeSheet();render();toast("Peça excluída")}catch(e){toast(e.message)}
}

